export type SupportedLanguage = 'en' | 'es' | 'ca' | 'va' | 'gl' | 'pt' | 'fr';

// Same order as the member app's picker.
export const SUPPORTED_LANGUAGES: SupportedLanguage[] = ['en', 'es', 'ca', 'va', 'gl', 'pt', 'fr'];

/**
 * Each language written in itself, never translated: somebody who opened
 * the dashboard in a language they cannot read has to recognise their own.
 */
export const LANGUAGE_NAMES: Record<SupportedLanguage, string> = {
  en: 'English',
  es: 'Español',
  ca: 'Català',
  va: 'Valencià',
  gl: 'Galego',
  pt: 'Português',
  fr: 'Français',
};

/**
 * The locale Intl formats dates with: Valencian has no code of its own and
 * uses Catalan's, and Portuguese is the European one.
 */
export function intlLocale(language: string): string {
  // British English: 24-hour times and day-month dates, as the rest of
  // the dashboard and the European places it serves (desktop review,
  // 2 Nov 2026: Events showed "06:30 PM" beside the dashboard's "18:30").
  if (language === 'en') return 'en-GB';
  if (language === 'va' || language === 'ca') return 'ca-ES';
  if (language === 'pt') return 'pt-PT';
  return language;
}

